//! Startup compatibility check against the Alembic-owned schema.
//!
//! `schema_revisions.txt` is generated by `scripts/sync_schema_revisions.py`
//! (oldest first, head last). Migrations follow expand/contract, so a database
//! that is *ahead* of this build stays compatible; only a database that is
//! *behind* is unsafe to serve.

const REVISIONS: &str = include_str!("../schema_revisions.txt");

pub fn revisions() -> impl Iterator<Item = &'static str> {
    REVISIONS
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
}

pub fn head() -> &'static str {
    revisions().last().expect("schema_revisions.txt is empty")
}

#[derive(Debug, PartialEq, Eq)]
pub enum SchemaStatus {
    Current,
    /// A known ancestor of `head()`: migrations have not run yet.
    Behind,
    /// Not known to this build, assumed to be a newer expand-only migration.
    Ahead,
    Missing,
}

pub fn classify(version: Option<&str>) -> SchemaStatus {
    match version {
        None => SchemaStatus::Missing,
        Some(version) if version == head() => SchemaStatus::Current,
        Some(version) if revisions().any(|known| known == version) => SchemaStatus::Behind,
        Some(_) => SchemaStatus::Ahead,
    }
}
